WITH cleaned AS (SELECT *, DAYOFWEEK(last_restock) AS last_restock_dayofweek FROM inventory WHERE last_restock > DATE '2024-02-13'), with_windows AS (SELECT *, NTILE(3) OVER (PARTITION BY store_id ORDER BY quantity DESC, id) AS quantity_bucket, AVG(quantity) OVER (PARTITION BY product_id, store_id ORDER BY quantity, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS quantity_avg_5, ROW_NUMBER() OVER (ORDER BY last_restock, id) AS row_seq, SUM(last_restock_dayofweek) OVER (PARTITION BY store_id, product_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_last_restock_dayofweek FROM cleaned), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_restock_dayofweek, id) AS rank_in_group FROM with_windows) ranked WHERE rank_in_group = 1), latest AS (SELECT * FROM ranked QUALIFY RANK() OVER (PARTITION BY store_id ORDER BY row_seq DESC) = 1), latest_inventory AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY row_seq DESC, id) AS rn FROM latest QUALIFY rn = 1), metrics AS (SELECT *, AVG(last_restock_dayofweek) OVER (ORDER BY cumulative_last_restock_dayofweek, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last_restock_dayofweek_avg_2, DENSE_RANK() OVER w_running AS row_seq_dense_rank FROM latest_inventory WINDOW w_running AS (PARTITION BY product_id, store_id ORDER BY row_seq NULLS FIRST)), summary AS (SELECT store_id, DATE_TRUNC('WEEK', last_restock) AS week_start, BIT_OR(quantity) AS quantity_bit_or, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT store_id) AS distinct_store_ids, COUNT(DISTINCT product_id) AS distinct_product_ids, ROUND(AVG(quantity), 2) AS avg_quantity, RANK() OVER (PARTITION BY store_id ORDER BY COUNT(DISTINCT product_id) DESC) AS distinct_product_ids_rank FROM metrics GROUP BY store_id, DATE_TRUNC('WEEK', last_restock)) SELECT s.store_id, s.week_start, s.quantity_bit_or, s.distinct_ids, s.distinct_store_ids, s.distinct_product_ids, (SELECT MIN(o2.discount) FROM orders o2 WHERE o2.store_id = s.store_id) AS min_order_discount FROM summary s
